-- ============================================================================
--  CineOps - Film Production Management Database      (MySQL 8.0.16+ / InnoDB)
--  01_schema.sql : creates the database, 52 tables, keys, constraints, indexes
--  Run from MySQL Workbench (File > Open SQL Script > run) or:  mysql -u root -p < 01_schema.sql
--  Generated by tools/make_ddl.py - table order = dependency order (parents first)
-- ============================================================================
DROP DATABASE IF EXISTS cineops;
CREATE DATABASE cineops CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE cineops;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE countries (
  country_id INT NOT NULL AUTO_INCREMENT,
  country_name VARCHAR(80) NOT NULL,
  iso_code VARCHAR(10),
  region ENUM('Africa','Antarctica','Asia','Europe','North America','Oceania','South America') NOT NULL,
  PRIMARY KEY (country_id),
  UNIQUE KEY uq_countries_iso_code (iso_code),
  UNIQUE KEY uq_countries_country_name (country_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Countries (reference data)';

CREATE TABLE languages (
  language_id INT NOT NULL AUTO_INCREMENT,
  iso_code VARCHAR(10) NOT NULL,
  language_name VARCHAR(30) NOT NULL,
  PRIMARY KEY (language_id),
  UNIQUE KEY uq_languages_iso_code (iso_code),
  UNIQUE KEY uq_languages_language_name (language_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Languages (reference data)';

CREATE TABLE departments (
  department_id INT NOT NULL AUTO_INCREMENT,
  department_name VARCHAR(30) NOT NULL,
  PRIMARY KEY (department_id),
  UNIQUE KEY uq_departments_department_name (department_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Crew departments - Camera, Sound, VFX ... (normalised lookup)';

CREATE TABLE genres (
  genre_id INT NOT NULL AUTO_INCREMENT,
  genre_name VARCHAR(20) NOT NULL,
  PRIMARY KEY (genre_id),
  UNIQUE KEY uq_genres_genre_name (genre_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Film genres (lookup)';

CREATE TABLE system_roles (
  role_id INT NOT NULL AUTO_INCREMENT,
  role_name VARCHAR(30) NOT NULL,
  PRIMARY KEY (role_id),
  UNIQUE KEY uq_system_roles_role_name (role_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Application security roles (RBAC)';

CREATE TABLE cities (
  city_id INT NOT NULL AUTO_INCREMENT,
  country_id INT NOT NULL,
  city_name VARCHAR(50) NOT NULL,
  latitude DECIMAL(9,6) NOT NULL,
  longitude DECIMAL(9,6) NOT NULL,
  population INT NOT NULL,
  timezone VARCHAR(50) NOT NULL,
  PRIMARY KEY (city_id),
  CONSTRAINT fk_cities_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Cities (reference data)';

CREATE TABLE industry_roles (
  role_id INT NOT NULL AUTO_INCREMENT,
  role_name VARCHAR(50) NOT NULL,
  description VARCHAR(80) NOT NULL,
  department_id INT NOT NULL,
  PRIMARY KEY (role_id),
  UNIQUE KEY uq_industry_roles_role_name (role_name),
  CONSTRAINT fk_industry_roles_department_id FOREIGN KEY (department_id) REFERENCES departments (department_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Film-industry job roles, each belongs to one department';

CREATE TABLE production_houses (
  production_house_id INT NOT NULL AUTO_INCREMENT,
  name VARCHAR(50) NOT NULL,
  legal_name VARCHAR(80) NOT NULL,
  founded_year SMALLINT NOT NULL,
  country_id INT NOT NULL,
  city_id INT NOT NULL,
  website VARCHAR(80) NOT NULL,
  email VARCHAR(80) NOT NULL,
  phone VARCHAR(20) NOT NULL,
  description VARCHAR(150) NOT NULL,
  company_size ENUM('Large','Medium','Small') NOT NULL,
  status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (production_house_id),
  UNIQUE KEY uq_production_houses_name (name),
  CONSTRAINT fk_production_houses_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_production_houses_city_id FOREIGN KEY (city_id) REFERENCES cities (city_id),
  CONSTRAINT chk_production_houses_founded CHECK (founded_year BETWEEN 1880 AND 2026)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Production companies';

CREATE TABLE vendors (
  vendor_id INT NOT NULL AUTO_INCREMENT,
  vendor_name VARCHAR(80) NOT NULL,
  vendor_type ENUM('Catering','Costume','Equipment','Insurance','Lighting & Grip','Location','Makeup','Post-production','Printing','Props & Set','Security','Transport','VFX') NOT NULL,
  country_id INT NOT NULL,
  city_id INT NOT NULL,
  email VARCHAR(80) NOT NULL,
  phone VARCHAR(20) NOT NULL,
  rating DECIMAL(6,2) NOT NULL,
  status ENUM('Active','Blacklisted','Inactive') NOT NULL DEFAULT 'Active',
  PRIMARY KEY (vendor_id),
  UNIQUE KEY uq_vendors_vendor_name (vendor_name),
  CONSTRAINT fk_vendors_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_vendors_city_id FOREIGN KEY (city_id) REFERENCES cities (city_id),
  CONSTRAINT chk_vendors_rating CHECK (rating BETWEEN 0 AND 5)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Equipment / service vendors';

CREATE TABLE distributors (
  distributor_id INT NOT NULL AUTO_INCREMENT,
  name VARCHAR(50) NOT NULL,
  company_type ENUM('Home Video / VOD','Regional Distributor','Sales Agent','Streaming Platform','Television Network','Theatrical') NOT NULL,
  country_id INT NOT NULL,
  city_id INT NOT NULL,
  website VARCHAR(80) NOT NULL,
  contact_email VARCHAR(80) NOT NULL,
  status ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',
  PRIMARY KEY (distributor_id),
  UNIQUE KEY uq_distributors_name (name),
  CONSTRAINT fk_distributors_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_distributors_city_id FOREIGN KEY (city_id) REFERENCES cities (city_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Distribution companies';

CREATE TABLE equipment (
  equipment_id INT NOT NULL AUTO_INCREMENT,
  equipment_name VARCHAR(50) NOT NULL,
  category ENUM('Audio','Camera','Drone','Editing workstation','Generator','Grip','Lens','Lighting','Monitor','Wireless/Other') NOT NULL,
  manufacturer VARCHAR(20) NOT NULL,
  model VARCHAR(50) NOT NULL,
  serial_number VARCHAR(20) NOT NULL,
  equipment_type VARCHAR(20) NOT NULL,
  daily_rental_rate DECIMAL(15,2) NOT NULL,
  replacement_cost DECIMAL(15,2) NOT NULL,
  vendor_id INT NOT NULL,
  availability_status ENUM('Available','Maintenance','Rented','Retired') NOT NULL DEFAULT 'Available',
  equipment_condition ENUM('Excellent','Fair','Good','Needs Service') NOT NULL,
  purchase_year SMALLINT NOT NULL,
  PRIMARY KEY (equipment_id),
  UNIQUE KEY uq_equipment_serial_number (serial_number),
  KEY idx_equipment_category (category),
  CONSTRAINT fk_equipment_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors (vendor_id),
  CONSTRAINT chk_equipment_prices CHECK (daily_rental_rate > 0 AND replacement_cost > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Equipment catalogue (cameras, lights, audio, grip ...)';

CREATE TABLE locations (
  location_id INT NOT NULL AUTO_INCREMENT,
  name VARCHAR(80) NOT NULL,
  location_type ENUM('Airport','Beach','Desert','Farm','Forest','Harbor','Heritage Site','Hospital','Hotel','House','Mountain','Nightclub','Office','Place of Worship','Police Station','Restaurant','School','Street','Studio','Warehouse') NOT NULL,
  country_id INT NOT NULL,
  city_id INT NOT NULL,
  latitude DECIMAL(9,6) NOT NULL,
  longitude DECIMAL(9,6) NOT NULL,
  indoor_outdoor ENUM('Both','Indoor','Outdoor') NOT NULL,
  description VARCHAR(80) NOT NULL,
  base_cost DECIMAL(15,2) NOT NULL,
  availability_status ENUM('Available','Booked','Unavailable') NOT NULL DEFAULT 'Available',
  PRIMARY KEY (location_id),
  CONSTRAINT fk_locations_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_locations_city_id FOREIGN KEY (city_id) REFERENCES cities (city_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Filming locations catalogue';

CREATE TABLE people (
  person_id INT NOT NULL AUTO_INCREMENT,
  name VARCHAR(100) NOT NULL,
  birth_year SMALLINT,
  gender ENUM('Female','Male'),
  country_id INT NOT NULL,
  city_id INT NOT NULL,
  bio VARCHAR(150) NOT NULL,
  profile_image VARCHAR(80) NOT NULL,
  contact_email VARCHAR(150) NOT NULL,
  phone VARCHAR(20) NOT NULL,
  union_name VARCHAR(50),
  availability_status ENUM('Available','Booked','On Hold','Unavailable') NOT NULL DEFAULT 'Available',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (person_id),
  UNIQUE KEY uq_people_contact_email (contact_email),
  KEY idx_people_name (name),
  CONSTRAINT fk_people_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_people_city_id FOREIGN KEY (city_id) REFERENCES cities (city_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Cast and crew (names are generated - anonymised)';

CREATE TABLE person_roles (
  person_role_id INT NOT NULL AUTO_INCREMENT,
  person_id INT NOT NULL,
  role_id INT NOT NULL,
  experience_years TINYINT NOT NULL,
  skill_level ENUM('Expert','Junior','Mid-level','Senior') NOT NULL,
  specialization VARCHAR(20),
  PRIMARY KEY (person_role_id),
  UNIQUE KEY uq_person_roles_person_id_role_id (person_id, role_id),
  CONSTRAINT fk_person_roles_person_id FOREIGN KEY (person_id) REFERENCES people (person_id) ON DELETE CASCADE,
  CONSTRAINT fk_person_roles_role_id FOREIGN KEY (role_id) REFERENCES industry_roles (role_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Roles/skills each person can perform';

CREATE TABLE films (
  film_id INT NOT NULL AUTO_INCREMENT,
  title VARCHAR(255) NOT NULL,
  original_title VARCHAR(255) NOT NULL,
  title_type ENUM('movie','tvMovie') NOT NULL,
  release_year SMALLINT,
  runtime_minutes SMALLINT NOT NULL,
  language_id INT NOT NULL,
  country_id INT NOT NULL,
  certificate VARCHAR(10) NOT NULL,
  synopsis VARCHAR(400) NOT NULL,
  poster_url VARCHAR(80) NOT NULL,
  imdb_rating DECIMAL(7,2),
  imdb_votes INT,
  PRIMARY KEY (film_id),
  KEY idx_films_title (title),
  CONSTRAINT fk_films_language_id FOREIGN KEY (language_id) REFERENCES languages (language_id),
  CONSTRAINT fk_films_country_id FOREIGN KEY (country_id) REFERENCES countries (country_id),
  CONSTRAINT chk_films_values CHECK (runtime_minutes > 0 AND (imdb_rating IS NULL OR imdb_rating BETWEEN 0 AND 10))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Film catalogue - one film per project';

CREATE TABLE film_genres (
  film_id INT NOT NULL,
  genre_id INT NOT NULL,
  is_primary BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (film_id, genre_id),
  CONSTRAINT fk_film_genres_film_id FOREIGN KEY (film_id) REFERENCES films (film_id) ON DELETE CASCADE,
  CONSTRAINT fk_film_genres_genre_id FOREIGN KEY (genre_id) REFERENCES genres (genre_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Many-to-many link films <-> genres';

CREATE TABLE characters (
  character_id INT NOT NULL AUTO_INCREMENT,
  film_id INT NOT NULL,
  character_name VARCHAR(50) NOT NULL,
  description VARCHAR(30) NOT NULL,
  character_type ENUM('Background','Cameo','Lead','Minor','Supporting') NOT NULL,
  importance_level TINYINT NOT NULL,
  PRIMARY KEY (character_id),
  CONSTRAINT fk_characters_film_id FOREIGN KEY (film_id) REFERENCES films (film_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Characters of a film';

CREATE TABLE projects (
  project_id INT NOT NULL AUTO_INCREMENT,
  film_id INT NOT NULL,
  project_code VARCHAR(20) NOT NULL,
  project_name VARCHAR(255) NOT NULL,
  project_type ENUM('Animated Feature','Co-production','Documentary Feature','Feature Film','Remake') NOT NULL,
  production_status ENUM('Completed','Development','In Production','Post-production','Pre-production') NOT NULL,
  preproduction_start DATE NOT NULL,
  production_start DATE NOT NULL,
  production_end DATE NOT NULL,
  postproduction_start DATE NOT NULL,
  planned_completion_date DATE NOT NULL,
  actual_completion_date DATE,
  planned_budget DECIMAL(15,2) NOT NULL,
  approved_budget DECIMAL(15,2) NOT NULL,
  current_budget DECIMAL(15,2) NOT NULL,
  priority ENUM('Critical','High','Low','Normal') NOT NULL,
  project_description VARCHAR(400) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (project_id),
  UNIQUE KEY uq_projects_project_code (project_code),
  KEY idx_projects_production_status (production_status),
  KEY idx_projects_planned_completion_date (planned_completion_date),
  CONSTRAINT fk_projects_film_id FOREIGN KEY (film_id) REFERENCES films (film_id),
  CONSTRAINT chk_projects_phase_dates CHECK (preproduction_start <= production_start AND production_start <= production_end AND production_end <= postproduction_start),
  CONSTRAINT chk_projects_budgets_positive CHECK (planned_budget > 0 AND approved_budget > 0 AND current_budget > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Production projects (core entity)';

CREATE TABLE project_production_houses (
  project_company_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  production_house_id INT NOT NULL,
  company_role ENUM('Co-production Partner','Financing Partner','Primary Producer','Production Partner') NOT NULL,
  ownership_percentage SMALLINT NOT NULL,
  PRIMARY KEY (project_company_id),
  UNIQUE KEY uq_project_production_houses_project_id_production_house_id (project_id, production_house_id),
  CONSTRAINT fk_project_production_houses_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id) ON DELETE CASCADE,
  CONSTRAINT fk_project_production_houses_production_house_id FOREIGN KEY (production_house_id) REFERENCES production_houses (production_house_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Production companies of a project (Primary Producer + partners)';

CREATE TABLE project_people (
  project_person_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  person_id INT NOT NULL,
  role_id INT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  employment_type ENUM('Contract','Day Player','Freelance','Full-time') NOT NULL,
  daily_rate DECIMAL(15,2) NOT NULL,
  status ENUM('Active','Completed','Scheduled') NOT NULL DEFAULT 'Scheduled',
  PRIMARY KEY (project_person_id),
  CONSTRAINT fk_project_people_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_project_people_person_id FOREIGN KEY (person_id) REFERENCES people (person_id),
  CONSTRAINT fk_project_people_role_id FOREIGN KEY (role_id) REFERENCES industry_roles (role_id),
  CONSTRAINT chk_project_people_dates CHECK (start_date <= end_date),
  CONSTRAINT chk_project_people_rate CHECK (daily_rate >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Key people (department heads, producers) engaged on a project';

CREATE TABLE media_assets (
  asset_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  asset_type ENUM('Call Sheet','Contract','Master','Receipt','Script') NOT NULL,
  filename VARCHAR(30) NOT NULL,
  file_extension ENUM('mxf','pdf') NOT NULL,
  storage_key VARCHAR(80) NOT NULL,
  file_size INT NOT NULL,
  uploaded_by INT NOT NULL,
  uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (asset_id),
  CONSTRAINT fk_media_assets_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_media_assets_uploaded_by FOREIGN KEY (uploaded_by) REFERENCES people (person_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Stored documents/files (scripts, call sheets, receipts ...)';

CREATE TABLE scripts (
  script_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  title VARCHAR(20) NOT NULL,
  author_id INT NOT NULL,
  file_asset_id INT NOT NULL,
  page_count SMALLINT NOT NULL,
  status ENUM('Approved','Draft','Locked') NOT NULL DEFAULT 'Draft',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  approved_at DATETIME,
  PRIMARY KEY (script_id),
  UNIQUE KEY uq_scripts_project_id (project_id),
  CONSTRAINT fk_scripts_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_scripts_author_id FOREIGN KEY (author_id) REFERENCES people (person_id),
  CONSTRAINT fk_scripts_file_asset_id FOREIGN KEY (file_asset_id) REFERENCES media_assets (asset_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Script of a project';

CREATE TABLE scenes (
  scene_id INT NOT NULL AUTO_INCREMENT,
  script_id INT NOT NULL,
  project_id INT NOT NULL,
  scene_number VARCHAR(10) NOT NULL,
  sequence_number TINYINT NOT NULL,
  heading VARCHAR(50) NOT NULL,
  description VARCHAR(80) NOT NULL,
  interior_exterior ENUM('EXT','INT') NOT NULL,
  location_type ENUM('Airport','Beach','Desert','Farm','Forest','Harbor','Heritage Site','Hospital','Hotel','House','Mountain','Nightclub','Office','Place of Worship','Police Station','Restaurant','School','Street','Studio','Warehouse') NOT NULL,
  time_of_day ENUM('Dawn','Day','Dusk','Night') NOT NULL,
  estimated_duration DECIMAL(7,2) NOT NULL,
  complexity_score TINYINT NOT NULL,
  vfx_required BOOLEAN NOT NULL DEFAULT 0,
  stunt_required BOOLEAN NOT NULL DEFAULT 0,
  special_effects_required BOOLEAN NOT NULL DEFAULT 0,
  night_shoot BOOLEAN NOT NULL DEFAULT 0,
  status ENUM('Completed','In Progress','Scheduled') NOT NULL DEFAULT 'Scheduled',
  location_id INT NOT NULL,
  script_pages DECIMAL(7,2) NOT NULL,
  dialogue_word_count SMALLINT NOT NULL,
  weather_dependent BOOLEAN NOT NULL DEFAULT 0,
  crew_required TINYINT NOT NULL,
  equipment_required TINYINT NOT NULL,
  camera_units TINYINT NOT NULL,
  lighting_units TINYINT NOT NULL,
  audio_units TINYINT NOT NULL,
  grip_units TINYINT NOT NULL,
  actual_duration_hours DECIMAL(7,2),
  PRIMARY KEY (scene_id),
  UNIQUE KEY uq_scenes_script_id_scene_number (script_id, scene_number),
  KEY idx_scenes_status (status),
  KEY idx_scenes_location_type (location_type),
  CONSTRAINT fk_scenes_script_id FOREIGN KEY (script_id) REFERENCES scripts (script_id),
  CONSTRAINT fk_scenes_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_scenes_location_id FOREIGN KEY (location_id) REFERENCES locations (location_id),
  CONSTRAINT chk_scenes_values CHECK (complexity_score BETWEEN 1 AND 10 AND estimated_duration > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Scenes of a script with their resource requirements';

CREATE TABLE scene_characters (
  scene_character_id INT NOT NULL AUTO_INCREMENT,
  scene_id INT NOT NULL,
  character_id INT NOT NULL,
  importance ENUM('Background','Principal','Supporting') NOT NULL,
  PRIMARY KEY (scene_character_id),
  UNIQUE KEY uq_scene_characters_scene_id_character_id (scene_id, character_id),
  CONSTRAINT fk_scene_characters_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id) ON DELETE CASCADE,
  CONSTRAINT fk_scene_characters_character_id FOREIGN KEY (character_id) REFERENCES characters (character_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Characters appearing in a scene';

CREATE TABLE contracts (
  contract_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  person_id INT,
  vendor_id INT,
  contract_type ENUM('Actor','Crew','Director','Equipment Rental','Location Agreement') NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  contract_value DECIMAL(15,2) NOT NULL,
  payment_terms VARCHAR(50) NOT NULL,
  status ENUM('Active','Completed','Pending') NOT NULL DEFAULT 'Pending',
  document_asset_id INT NOT NULL,
  PRIMARY KEY (contract_id),
  KEY idx_contracts_status (status),
  CONSTRAINT fk_contracts_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_contracts_person_id FOREIGN KEY (person_id) REFERENCES people (person_id),
  CONSTRAINT fk_contracts_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors (vendor_id),
  CONSTRAINT fk_contracts_document_asset_id FOREIGN KEY (document_asset_id) REFERENCES media_assets (asset_id),
  CONSTRAINT chk_contracts_dates CHECK (start_date <= end_date),
  CONSTRAINT chk_contracts_value CHECK (contract_value >= 0),
  CONSTRAINT chk_contracts_person_xor_vendor CHECK ((person_id IS NOT NULL) + (vendor_id IS NOT NULL) = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Contracts with a person OR a vendor';

CREATE TABLE payments (
  payment_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  contract_id INT,
  vendor_id INT,
  person_id INT,
  amount DECIMAL(15,2) NOT NULL,
  payment_date DATE NOT NULL,
  payment_type ENUM('Advance','Final','Invoice Settlement','Milestone') NOT NULL,
  payment_status ENUM('Completed','Scheduled') NOT NULL DEFAULT 'Scheduled',
  transaction_reference VARCHAR(20) NOT NULL,
  PRIMARY KEY (payment_id),
  UNIQUE KEY uq_payments_transaction_reference (transaction_reference),
  KEY idx_payments_payment_date (payment_date),
  CONSTRAINT fk_payments_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_payments_contract_id FOREIGN KEY (contract_id) REFERENCES contracts (contract_id),
  CONSTRAINT fk_payments_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors (vendor_id),
  CONSTRAINT fk_payments_person_id FOREIGN KEY (person_id) REFERENCES people (person_id),
  CONSTRAINT chk_payments_amount CHECK (amount > 0),
  CONSTRAINT chk_payments_person_xor_vendor CHECK ((person_id IS NOT NULL) + (vendor_id IS NOT NULL) = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Payments against contracts';

CREATE TABLE cast_assignments (
  cast_assignment_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  person_id INT NOT NULL,
  character_id INT NOT NULL,
  contract_id INT,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  salary DECIMAL(15,2) NOT NULL,
  status ENUM('Active','Completed','Replaced','Scheduled') NOT NULL DEFAULT 'Scheduled',
  assignment_type ENUM('Principal','Replacement','Stunt Double','Voice','Younger Version') NOT NULL,
  PRIMARY KEY (cast_assignment_id),
  CONSTRAINT fk_cast_assignments_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_cast_assignments_person_id FOREIGN KEY (person_id) REFERENCES people (person_id),
  CONSTRAINT fk_cast_assignments_character_id FOREIGN KEY (character_id) REFERENCES characters (character_id),
  CONSTRAINT fk_cast_assignments_contract_id FOREIGN KEY (contract_id) REFERENCES contracts (contract_id),
  CONSTRAINT chk_cast_assignments_dates CHECK (start_date <= end_date),
  CONSTRAINT chk_cast_assignments_salary CHECK (salary >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Actors cast to characters';

CREATE TABLE location_bookings (
  booking_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  location_id INT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  booking_cost DECIMAL(15,2) NOT NULL,
  deposit DECIMAL(15,2) NOT NULL,
  status ENUM('Completed','Confirmed','Pending') NOT NULL DEFAULT 'Pending',
  permit_required BOOLEAN NOT NULL DEFAULT 0,
  permit_status ENUM('Approved','Not Required','Pending') NOT NULL DEFAULT 'Pending',
  PRIMARY KEY (booking_id),
  CONSTRAINT fk_location_bookings_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_location_bookings_location_id FOREIGN KEY (location_id) REFERENCES locations (location_id),
  CONSTRAINT chk_location_bookings_dates CHECK (start_date <= end_date),
  CONSTRAINT chk_location_bookings_cost CHECK (booking_cost >= 0 AND deposit >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Location reservations and permits';

CREATE TABLE shoot_days (
  shoot_day_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  shoot_date DATE NOT NULL,
  day_number SMALLINT NOT NULL,
  location_id INT NOT NULL,
  call_time TIME NOT NULL,
  wrap_time TIME NOT NULL,
  planned_hours DECIMAL(7,2) NOT NULL,
  actual_hours DECIMAL(7,2),
  weather_condition ENUM('Clear','Cloudy','Fog','Heatwave','Heavy Rain','Light Rain','Snow','Storm','Windy') NOT NULL,
  weather_risk DECIMAL(7,3) NOT NULL,
  status ENUM('Cancelled','Completed','Scheduled') NOT NULL DEFAULT 'Scheduled',
  delay_minutes SMALLINT,
  is_added_day BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (shoot_day_id),
  UNIQUE KEY uq_shoot_days_project_id_day_number (project_id, day_number),
  KEY idx_shoot_days_shoot_date (shoot_date),
  CONSTRAINT fk_shoot_days_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_shoot_days_location_id FOREIGN KEY (location_id) REFERENCES locations (location_id),
  CONSTRAINT chk_shoot_days_values CHECK (planned_hours > 0 AND day_number > 0 AND weather_risk BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Scheduled / actual shooting days';

CREATE TABLE shoot_day_scenes (
  shoot_day_scene_id INT NOT NULL AUTO_INCREMENT,
  shoot_day_id INT NOT NULL,
  scene_id INT NOT NULL,
  planned_start DATETIME NOT NULL,
  planned_end DATETIME NOT NULL,
  actual_start DATETIME,
  actual_end DATETIME,
  status ENUM('Completed','Rescheduled','Scheduled') NOT NULL DEFAULT 'Scheduled',
  delay_minutes SMALLINT,
  PRIMARY KEY (shoot_day_scene_id),
  KEY idx_shoot_day_scenes_status (status),
  CONSTRAINT fk_shoot_day_scenes_shoot_day_id FOREIGN KEY (shoot_day_id) REFERENCES shoot_days (shoot_day_id) ON DELETE CASCADE,
  CONSTRAINT fk_shoot_day_scenes_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id) ON DELETE CASCADE,
  CONSTRAINT chk_shoot_day_scenes_planned_times CHECK (planned_start <= planned_end)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Scenes planned/shot on a shoot day';

CREATE TABLE call_sheets (
  call_sheet_id INT NOT NULL AUTO_INCREMENT,
  shoot_day_id INT NOT NULL,
  version TINYINT NOT NULL,
  issue_date DATE NOT NULL,
  general_call_time TIME NOT NULL,
  weather_info VARCHAR(50) NOT NULL,
  special_instructions VARCHAR(200) NOT NULL,
  status ENUM('Draft','Issued','Superseded') NOT NULL DEFAULT 'Draft',
  file_asset_id INT NOT NULL,
  PRIMARY KEY (call_sheet_id),
  UNIQUE KEY uq_call_sheets_shoot_day_id_version (shoot_day_id, version),
  CONSTRAINT fk_call_sheets_shoot_day_id FOREIGN KEY (shoot_day_id) REFERENCES shoot_days (shoot_day_id),
  CONSTRAINT fk_call_sheets_file_asset_id FOREIGN KEY (file_asset_id) REFERENCES media_assets (asset_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Daily call sheets';

CREATE TABLE crew_assignments (
  assignment_id INT NOT NULL AUTO_INCREMENT,
  person_id INT NOT NULL,
  shoot_day_id INT NOT NULL,
  role_id INT NOT NULL,
  call_time TIME,
  wrap_time TIME,
  hours_worked DECIMAL(7,2) NOT NULL,
  overtime_hours DECIMAL(7,2) NOT NULL,
  attendance_status ENUM('Absent','Late','Present') NOT NULL,
  daily_rate DECIMAL(15,2) NOT NULL,
  PRIMARY KEY (assignment_id),
  UNIQUE KEY uq_crew_assignments_person_id_shoot_day_id (person_id, shoot_day_id),
  CONSTRAINT fk_crew_assignments_person_id FOREIGN KEY (person_id) REFERENCES people (person_id),
  CONSTRAINT fk_crew_assignments_shoot_day_id FOREIGN KEY (shoot_day_id) REFERENCES shoot_days (shoot_day_id),
  CONSTRAINT fk_crew_assignments_role_id FOREIGN KEY (role_id) REFERENCES industry_roles (role_id),
  CONSTRAINT chk_crew_assignments_hours CHECK (hours_worked >= 0 AND overtime_hours >= 0 AND daily_rate >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Crew attendance per shoot day';

CREATE TABLE equipment_rentals (
  rental_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  equipment_id INT NOT NULL,
  vendor_id INT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  planned_cost DECIMAL(15,2) NOT NULL,
  actual_cost DECIMAL(15,2),
  pickup_date DATE,
  return_date DATE,
  late_return BOOLEAN NOT NULL DEFAULT 0,
  damage_status ENUM('Major','Minor'),
  status ENUM('Active','Reserved','Returned') NOT NULL DEFAULT 'Active',
  PRIMARY KEY (rental_id),
  CONSTRAINT fk_equipment_rentals_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_equipment_rentals_equipment_id FOREIGN KEY (equipment_id) REFERENCES equipment (equipment_id),
  CONSTRAINT fk_equipment_rentals_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors (vendor_id),
  CONSTRAINT chk_equipment_rentals_dates CHECK (start_date <= end_date),
  CONSTRAINT chk_equipment_rentals_cost CHECK (planned_cost >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Equipment rented by a project';

CREATE TABLE scene_equipment (
  scene_equipment_id INT NOT NULL AUTO_INCREMENT,
  scene_id INT NOT NULL,
  rental_id INT NOT NULL,
  quantity TINYINT NOT NULL,
  PRIMARY KEY (scene_equipment_id),
  UNIQUE KEY uq_scene_equipment_scene_id_rental_id (scene_id, rental_id),
  CONSTRAINT fk_scene_equipment_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id) ON DELETE CASCADE,
  CONSTRAINT fk_scene_equipment_rental_id FOREIGN KEY (rental_id) REFERENCES equipment_rentals (rental_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Rented equipment used by a scene (generated link)';

CREATE TABLE budgets (
  budget_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  version TINYINT NOT NULL,
  total_budget DECIMAL(15,2) NOT NULL,
  approved_amount DECIMAL(15,2) NOT NULL,
  contingency_amount DECIMAL(15,2) NOT NULL,
  status ENUM('Approved','Closed','Draft') NOT NULL DEFAULT 'Draft',
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (budget_id),
  UNIQUE KEY uq_budgets_project_id_version (project_id, version),
  CONSTRAINT fk_budgets_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT chk_budgets_amounts CHECK (total_budget > 0 AND approved_amount >= 0 AND contingency_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Project budget (header)';

CREATE TABLE budget_departments (
  budget_department_id INT NOT NULL AUTO_INCREMENT,
  budget_id INT NOT NULL,
  category ENUM('Cast','Catering','Crew','Equipment','Locations','Marketing & Distribution','Post-production','Production Design','Transport','VFX') NOT NULL,
  allocated_amount DECIMAL(15,2) NOT NULL,
  spent_amount DECIMAL(15,2) NOT NULL,
  remaining_amount DECIMAL(15,2) GENERATED ALWAYS AS (allocated_amount - spent_amount) STORED,
  PRIMARY KEY (budget_department_id),
  CONSTRAINT fk_budget_departments_budget_id FOREIGN KEY (budget_id) REFERENCES budgets (budget_id) ON DELETE CASCADE,
  CONSTRAINT chk_budget_departments_amounts CHECK (allocated_amount >= 0 AND spent_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Budget split by cost category; spent_amount maintained by trigger';

CREATE TABLE expenses (
  expense_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  budget_department_id INT NOT NULL,
  vendor_id INT,
  expense_category ENUM('Cast Overage','Cast Salary','Catering','Costume','Crew Payroll','Delay Costs','Equipment Rental','Insurance','Legal & Admin','Location Fee','Location Overage','Makeup & Hair','Marketing','Permit','Post-production','Props & Set','Talent Fee','Unit Transport','VFX Vendor') NOT NULL,
  description VARCHAR(50) NOT NULL,
  amount DECIMAL(15,2) NOT NULL,
  tax_amount DECIMAL(15,2) NOT NULL,
  expense_date DATE NOT NULL,
  payment_status ENUM('Approved','Disputed','Paid','Pending') NOT NULL DEFAULT 'Pending',
  approved_by INT NOT NULL,
  receipt_asset_id INT,
  PRIMARY KEY (expense_id),
  KEY idx_expenses_expense_date (expense_date),
  CONSTRAINT fk_expenses_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_expenses_budget_department_id FOREIGN KEY (budget_department_id) REFERENCES budget_departments (budget_department_id),
  CONSTRAINT fk_expenses_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors (vendor_id),
  CONSTRAINT fk_expenses_approved_by FOREIGN KEY (approved_by) REFERENCES people (person_id),
  CONSTRAINT fk_expenses_receipt_asset_id FOREIGN KEY (receipt_asset_id) REFERENCES media_assets (asset_id),
  CONSTRAINT chk_expenses_amounts CHECK (amount > 0 AND tax_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Expenses booked against a budget category';

CREATE TABLE production_events (
  event_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  shoot_day_id INT NOT NULL,
  scene_id INT,
  event_type ENUM('Actor Unavailable','Equipment Failure','Location Problem','Permit Issue','Power Failure','Safety Issue','Script Change','Technical Problem','Transport Delay','Weather Delay') NOT NULL,
  severity ENUM('Critical','High','Low','Medium') NOT NULL,
  start_time DATETIME NOT NULL,
  end_time DATETIME NOT NULL,
  duration_minutes SMALLINT NOT NULL,
  description VARCHAR(80) NOT NULL,
  resolved BOOLEAN NOT NULL DEFAULT 0,
  department_id INT NOT NULL,
  PRIMARY KEY (event_id),
  KEY idx_production_events_event_type (event_type),
  CONSTRAINT fk_production_events_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_production_events_shoot_day_id FOREIGN KEY (shoot_day_id) REFERENCES shoot_days (shoot_day_id),
  CONSTRAINT fk_production_events_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id),
  CONSTRAINT fk_production_events_department_id FOREIGN KEY (department_id) REFERENCES departments (department_id),
  CONSTRAINT chk_production_events_times CHECK (start_time <= end_time AND duration_minutes >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='On-set incident log';

CREATE TABLE production_delays (
  delay_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  shoot_day_id INT NOT NULL,
  scene_id INT,
  delay_type ENUM('Cast','Creative','Equipment','Location','Permit','Power','Safety','Schedule Overrun','Technical','Transport','Weather') NOT NULL,
  cause VARCHAR(80) NOT NULL,
  delay_minutes SMALLINT NOT NULL,
  severity ENUM('Major','Moderate','Severe') NOT NULL,
  weather_related BOOLEAN NOT NULL DEFAULT 0,
  equipment_related BOOLEAN NOT NULL DEFAULT 0,
  crew_related BOOLEAN NOT NULL DEFAULT 0,
  location_related BOOLEAN NOT NULL DEFAULT 0,
  cost_impact DECIMAL(15,2) NOT NULL,
  event_id INT,
  department_id INT NOT NULL,
  PRIMARY KEY (delay_id),
  KEY idx_production_delays_delay_type (delay_type),
  CONSTRAINT fk_production_delays_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_production_delays_shoot_day_id FOREIGN KEY (shoot_day_id) REFERENCES shoot_days (shoot_day_id),
  CONSTRAINT fk_production_delays_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id),
  CONSTRAINT fk_production_delays_event_id FOREIGN KEY (event_id) REFERENCES production_events (event_id),
  CONSTRAINT fk_production_delays_department_id FOREIGN KEY (department_id) REFERENCES departments (department_id),
  CONSTRAINT chk_production_delays_values CHECK (delay_minutes >= 0 AND cost_impact >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Delays (optionally caused by an incident)';

CREATE TABLE post_production (
  postproduction_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  editing_progress DECIMAL(8,2) NOT NULL,
  vfx_progress DECIMAL(8,2) NOT NULL,
  audio_progress DECIMAL(8,2) NOT NULL,
  color_progress DECIMAL(8,2) NOT NULL,
  subtitle_progress DECIMAL(8,2) NOT NULL,
  current_stage ENUM('Color Grading','Delivered','Editing','Subtitles','VFX') NOT NULL,
  status ENUM('Completed','Delayed','In Progress','Not Started') NOT NULL DEFAULT 'Not Started',
  overall_progress DECIMAL(5,2) GENERATED ALWAYS AS ((editing_progress + vfx_progress + audio_progress + color_progress + subtitle_progress) / 5) STORED,
  PRIMARY KEY (postproduction_id),
  UNIQUE KEY uq_post_production_project_id (project_id),
  CONSTRAINT fk_post_production_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT chk_post_production_progress CHECK (editing_progress BETWEEN 0 AND 100 AND vfx_progress BETWEEN 0 AND 100 AND audio_progress BETWEEN 0 AND 100 AND color_progress BETWEEN 0 AND 100 AND subtitle_progress BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Post-production progress (1 per project)';

CREATE TABLE postproduction_tasks (
  task_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  task_category ENUM('Color Grading','Editing','Mastering','Music','Sound','Subtitles','VFX') NOT NULL,
  task_type VARCHAR(30) NOT NULL,
  assigned_to INT,
  asset_id INT,
  start_date DATE NOT NULL,
  due_date DATE NOT NULL,
  completion_date DATE,
  progress DECIMAL(8,2) NOT NULL,
  status ENUM('Completed','In Progress','Not Started') NOT NULL DEFAULT 'Not Started',
  PRIMARY KEY (task_id),
  CONSTRAINT fk_postproduction_tasks_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_postproduction_tasks_assigned_to FOREIGN KEY (assigned_to) REFERENCES people (person_id),
  CONSTRAINT fk_postproduction_tasks_asset_id FOREIGN KEY (asset_id) REFERENCES media_assets (asset_id),
  CONSTRAINT chk_postproduction_tasks_dates CHECK (start_date <= due_date),
  CONSTRAINT chk_postproduction_tasks_progress CHECK (progress BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Post-production work items';

CREATE TABLE distribution (
  distribution_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  distributor_id INT,
  platform ENUM('Cinema','Festival','Home Video / VOD','International Sales','Streaming','TV') NOT NULL,
  territory VARCHAR(10) NOT NULL,
  release_type ENUM('Digital Release','Festival / Sales','Festival Premiere','Limited Theatrical','Streaming Premiere','TV Broadcast','Wide Theatrical') NOT NULL,
  release_date DATE NOT NULL,
  language_id INT NOT NULL,
  certificate VARCHAR(10) NOT NULL,
  deal_value DECIMAL(15,2),
  status ENUM('Negotiating','Released','Scheduled','Signed') NOT NULL DEFAULT 'Scheduled',
  PRIMARY KEY (distribution_id),
  CONSTRAINT fk_distribution_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_distribution_distributor_id FOREIGN KEY (distributor_id) REFERENCES distributors (distributor_id),
  CONSTRAINT fk_distribution_language_id FOREIGN KEY (language_id) REFERENCES languages (language_id),
  CONSTRAINT chk_distribution_deal CHECK (deal_value IS NULL OR deal_value >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Releases and distribution deals';

CREATE TABLE users (
  user_id INT NOT NULL AUTO_INCREMENT,
  person_id INT,
  email VARCHAR(80) NOT NULL,
  password_hash VARCHAR(100) NOT NULL,
  account_status ENUM('Active','Pending','Suspended') NOT NULL DEFAULT 'Pending',
  last_login DATETIME,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_users_email (email),
  CONSTRAINT fk_users_person_id FOREIGN KEY (person_id) REFERENCES people (person_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Application users';

CREATE TABLE user_roles (
  user_role_id INT NOT NULL AUTO_INCREMENT,
  user_id INT NOT NULL,
  role_id INT NOT NULL,
  organization_id INT,
  project_id INT,
  PRIMARY KEY (user_role_id),
  CONSTRAINT fk_user_roles_user_id FOREIGN KEY (user_id) REFERENCES users (user_id) ON DELETE CASCADE,
  CONSTRAINT fk_user_roles_role_id FOREIGN KEY (role_id) REFERENCES system_roles (role_id),
  CONSTRAINT fk_user_roles_organization_id FOREIGN KEY (organization_id) REFERENCES production_houses (production_house_id),
  CONSTRAINT fk_user_roles_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Role of a user in an organisation / project';

CREATE TABLE audit_logs (
  audit_id INT NOT NULL AUTO_INCREMENT,
  user_id INT,
  action VARCHAR(10) NOT NULL,
  entity_type ENUM('budget','call_sheet','contract','expense','project','script','shoot_day','user') NOT NULL,
  entity_id INT NOT NULL,
  old_value VARCHAR(30),
  new_value VARCHAR(50),
  ip_address VARCHAR(20) NOT NULL,
  logged_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (audit_id),
  KEY idx_audit_logs_entity_type_entity_id (entity_type, entity_id),
  KEY idx_audit_logs_logged_at (logged_at),
  CONSTRAINT fk_audit_logs_user_id FOREIGN KEY (user_id) REFERENCES users (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Audit trail (sample + trigger generated)';

CREATE TABLE ml_project_split (
  project_id INT NOT NULL,
  split ENUM('test','train','validation') NOT NULL,
  PRIMARY KEY (project_id),
  CONSTRAINT fk_ml_project_split_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML: train/validation/test split, one per project (shared by all ML datasets)';

CREATE TABLE ml_scene_features (
  scene_id INT NOT NULL,
  day_night ENUM('Day','Night') NOT NULL,
  location_change BOOLEAN NOT NULL DEFAULT 0,
  historical_scene_duration DECIMAL(7,3) NOT NULL,
  PRIMARY KEY (scene_id),
  CONSTRAINT fk_ml_scene_features_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML: computed per-scene features not stored in scenes';

CREATE TABLE ml_production_risk (
  risk_sample_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  snapshot_day SMALLINT NOT NULL,
  snapshot_date DATE NOT NULL,
  budget_used_pct DOUBLE NOT NULL,
  production_progress DECIMAL(7,3) NOT NULL,
  days_completed_pct DOUBLE NOT NULL,
  days_remaining SMALLINT NOT NULL,
  scenes_remaining SMALLINT NOT NULL,
  crew_availability_pct DOUBLE NOT NULL,
  equipment_availability_pct DOUBLE NOT NULL,
  location_changes TINYINT NOT NULL,
  previous_delay_count SMALLINT NOT NULL,
  equipment_delay_count TINYINT NOT NULL,
  crew_absence_count SMALLINT NOT NULL,
  weather_risk DOUBLE NOT NULL,
  production_event_count SMALLINT NOT NULL,
  daily_burn_rate DECIMAL(15,2) NOT NULL,
  current_schedule_variance DOUBLE NOT NULL,
  delay_occurred BOOLEAN NOT NULL DEFAULT 0,
  delay_days TINYINT NOT NULL,
  risk_category ENUM('Critical','High','Low','Medium') NOT NULL,
  PRIMARY KEY (risk_sample_id),
  CONSTRAINT fk_ml_production_risk_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML dataset: risk snapshots (target delay_occurred)';

CREATE TABLE ml_budget_forecast (
  budget_sample_id INT NOT NULL AUTO_INCREMENT,
  project_id INT NOT NULL,
  snapshot_day SMALLINT NOT NULL,
  snapshot_date DATE NOT NULL,
  original_budget DECIMAL(15,2) NOT NULL,
  approved_budget DECIMAL(15,2) NOT NULL,
  budget_used DECIMAL(15,2) NOT NULL,
  budget_used_pct DOUBLE NOT NULL,
  days_completed SMALLINT NOT NULL,
  days_remaining SMALLINT NOT NULL,
  daily_burn_rate DECIMAL(15,2) NOT NULL,
  cast_cost DECIMAL(15,2) NOT NULL,
  crew_cost DECIMAL(15,2) NOT NULL,
  equipment_cost DECIMAL(15,2) NOT NULL,
  location_cost DECIMAL(15,2) NOT NULL,
  transport_cost DECIMAL(15,2) NOT NULL,
  catering_cost DECIMAL(15,2) NOT NULL,
  production_design_cost DECIMAL(15,2) NOT NULL,
  vfx_cost DECIMAL(15,2) NOT NULL,
  postproduction_cost DECIMAL(15,2) NOT NULL,
  delay_cost DECIMAL(15,2) NOT NULL,
  production_progress DECIMAL(7,3) NOT NULL,
  scenes_completed SMALLINT NOT NULL,
  scenes_remaining SMALLINT NOT NULL,
  final_cost DECIMAL(15,2) NOT NULL,
  budget_overrun DECIMAL(15,2) NOT NULL,
  budget_overrun_pct DOUBLE NOT NULL,
  over_budget BOOLEAN NOT NULL DEFAULT 0,
  PRIMARY KEY (budget_sample_id),
  CONSTRAINT fk_ml_budget_forecast_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML dataset: budget snapshots (target budget_overrun_pct / over_budget)';

CREATE TABLE ml_crew_recommendation (
  sample_id INT NOT NULL AUTO_INCREMENT,
  requirement_id INT NOT NULL,
  project_id INT NOT NULL,
  role_id INT NOT NULL,
  experience_required TINYINT NOT NULL,
  project_scale ENUM('high','low','micro','mid','tentpole') NOT NULL,
  project_country_id INT NOT NULL,
  candidate_person_id INT NOT NULL,
  same_country BOOLEAN NOT NULL DEFAULT 0,
  availability BOOLEAN NOT NULL DEFAULT 0,
  previous_project_count TINYINT NOT NULL,
  historical_assignment_count TINYINT NOT NULL,
  label BOOLEAN NOT NULL DEFAULT 0,
  required_skill_level TINYINT NOT NULL,
  PRIMARY KEY (sample_id),
  CONSTRAINT fk_ml_crew_recommendation_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_ml_crew_recommendation_role_id FOREIGN KEY (role_id) REFERENCES industry_roles (role_id),
  CONSTRAINT fk_ml_crew_recommendation_project_country_id FOREIGN KEY (project_country_id) REFERENCES countries (country_id),
  CONSTRAINT fk_ml_crew_recommendation_candidate_person_id FOREIGN KEY (candidate_person_id) REFERENCES people (person_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML dataset: crew candidate pairs (target label)';

CREATE TABLE ml_models (
  model_id INT NOT NULL AUTO_INCREMENT,
  model_name VARCHAR(60) NOT NULL,
  source_view VARCHAR(60) NOT NULL,
  target_column VARCHAR(60) NOT NULL,
  task_type ENUM('classification','regression') NOT NULL,
  algorithm VARCHAR(60) NOT NULL,
  n_train INT NOT NULL,
  n_test INT NOT NULL,
  metric_1_name VARCHAR(30) NOT NULL,
  metric_1_value DOUBLE NOT NULL,
  metric_2_name VARCHAR(30) NULL,
  metric_2_value DOUBLE NULL,
  trained_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (model_id),
  UNIQUE KEY uq_ml_models_name (model_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML: trained models and their metrics';

CREATE TABLE ml_predictions (
  prediction_id INT NOT NULL AUTO_INCREMENT,
  model_id INT NOT NULL,
  sample_id INT NOT NULL,
  project_id INT NULL,
  scene_id INT NULL,
  actual_value DOUBLE NOT NULL,
  predicted_value DOUBLE NOT NULL,
  PRIMARY KEY (prediction_id),
  UNIQUE KEY uq_ml_predictions_model_sample (model_id, sample_id),
  CONSTRAINT fk_ml_predictions_model_id FOREIGN KEY (model_id) REFERENCES ml_models (model_id) ON DELETE CASCADE,
  CONSTRAINT fk_ml_predictions_project_id FOREIGN KEY (project_id) REFERENCES projects (project_id),
  CONSTRAINT fk_ml_predictions_scene_id FOREIGN KEY (scene_id) REFERENCES scenes (scene_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='ML: predictions on the test split';

SET FOREIGN_KEY_CHECKS = 1;
SELECT CONCAT('Schema created: ', COUNT(*), ' tables') AS result FROM information_schema.tables WHERE table_schema = 'cineops' AND table_type = 'BASE TABLE';
